// Load a fresh copy of storage, like the app starting again (the fake disk is kept)
function freshStorage(): typeof import("../data/storage") {
  let storage!: typeof import("../data/storage"); // filled in below
  jest.isolateModules(() => {
    storage = require("../data/storage"); // re-run the module from scratch
  });
  return storage; // hand back the new copy
}

const eggs = createIngredient("Eggs", ["piece"], "Proteins", "eggs"); // count-only ingredient
const oats = createIngredient("Oats", ["g", "kg"], "Carbs", "oats"); // mass ingredient
const oatsBowl = createRecipe("Oats Bowl", [{ ingredientId: "oats", amount: 80, unit: "g" }], { id: "r1", category: "Breakfast" }); // simple recipe

beforeEach(() => disk.clear()); // every test starts with nothing saved

test("loads nothing before anything is saved", () => {
  const storage = freshStorage(); // first app start
  expect(storage.loadRecipe()).toEqual([]); // no recipes yet
  expect(storage.loadIngredient()).toEqual([]); // no ingredients yet
});

test("ingredients survive an app reload", () => {
  freshStorage().saveIngredient(eggs); // save in one "session"
  freshStorage().saveIngredient(oats); // and another in a second one
  expect(freshStorage().loadIngredient()).toEqual([eggs, oats]); // both come back after reload
});

test("recipes survive an app reload", () => {
  freshStorage().saveRecipe(oatsBowl); // save, then "close the app"
  expect(freshStorage().loadRecipe()).toEqual([oatsBowl]); // same recipe after reload
});

test("saving with an existing id replaces it instead of duplicating", () => {
  const storage = freshStorage(); // one session
  storage.saveIngredient(oats); // first version
  storage.saveIngredient({ ...oats, name: "Rolled Oats" }); // edited, same id
  expect(freshStorage().loadIngredient()).toEqual([{ ...oats, name: "Rolled Oats" }]); // only the edit remains
});

test("delete removes only the matching id", () => {
  const storage = freshStorage(); // one session
  storage.saveIngredient(eggs); // keep this one
  storage.saveIngredient(oats); // delete this one
  storage.deleteIngredient("oats"); // remove by id
  storage.saveRecipe(oatsBowl); // a recipe to delete
  storage.deleteRecipe("r1"); // remove by id
  const reloaded = freshStorage(); // reload the app
  expect(reloaded.loadIngredient()).toEqual([eggs]); // eggs left
  expect(reloaded.loadRecipe()).toEqual([]); // recipe gone
});

test("old-format and invalid entries are skipped on load", () => {
  disk.set("ingredients.json", JSON.stringify([
    { name: "Apple", quantity: { amount: 1, unit: "piece" }, type: "Fruit" }, // old class-based shape
    { ...eggs, allowedUnits: ["handful"] }, // unknown unit
    eggs, // valid
  ]));
  disk.set("recipes.json", JSON.stringify([
    { Pie: { Apple: { quantity: { amount: 1, unit: "piece" } } } }, // old { [name]: {...} } shape
    { ...oatsBowl, items: [{ ingredientId: "oats", amount: -5, unit: "g" }] }, // negative amount
    oatsBowl, // valid
  ]));
  const storage = freshStorage(); // app starts with that data on disk
  expect(storage.loadIngredient()).toEqual([eggs]); // only the valid ingredient
  expect(storage.loadRecipe()).toEqual([oatsBowl]); // only the valid recipe
});

test("a corrupt file loads as empty instead of crashing", () => {
  disk.set("recipes.json", "{not json"); // broken contents
  expect(freshStorage().loadRecipe()).toEqual([]); // treated as nothing saved
});

